class BinaryDataProcessor:
    NON_BINARY_CHARS = [c for c in '01' if c in '01']
    BYTE_LENGTH = 8
    ZERO_CHAR = '0'
    ONE_CHAR = '1'

    def __init__(self, binary_string):
        self.binary_string = binary_string
        self.clean_non_binary_chars()

    def clean_non_binary_chars(self):
        self.binary_string = ''.join(filter(lambda x: x in '01', self.binary_string))

    def get_zeroes_count(self):
        return self.binary_string.count(self.ZERO_CHAR)

    def get_ones_count(self):
        return self.binary_string.count(self.ONE_CHAR)

    def get_total_length(self):
        return len(self.binary_string)

    def calculate_binary_info(self):
        zeroes_count = self.get_zeroes_count()
        ones_count = self.get_ones_count()
        total_length = self.get_total_length()

        zeroes_percentage = (zeroes_count / total_length) if total_length else 0
        ones_percentage = (ones_count / total_length) if total_length else 0

        return {
            'Zeroes': zeroes_percentage,
            'Ones': ones_percentage,
            'Bit length': total_length
        }

    def _binary_to_byte_array(self):
        byte_array = bytearray()
        for i in range(0, len(self.binary_string), self.BYTE_LENGTH):
            byte = self.binary_string[i:i+self.BYTE_LENGTH]
            if len(byte) < self.BYTE_LENGTH:
                break
            decimal = int(byte, 2)
            byte_array.append(decimal)
        return byte_array

    def convert_to_ascii(self):
        byte_array = self._binary_to_byte_array()
        return byte_array.decode('ascii')

    def convert_to_utf8(self):
        byte_array = self._binary_to_byte_array()
        return byte_array.decode('utf-8')
